/**
 * ThemeService — Centralized CSS color and theme variable access.
 *
 * All chart, table, and view modules should read colors through `getThemeColors()`
 * rather than querying the DOM directly.
 *
 * Cache strategy:  TTL-based (5 s) with optional `forceRefresh`.
 * Call `invalidateThemeColorCache()` after a theme or mode switch to force re-read.
 *
 * Competence-level colors are **not** read from CSS — they depend on the level scale
 * in the loaded data and are generated by `competenceLevelColors`. This module just
 * re-exposes them alongside the rest of the palette.
 * @module themeService
 */

import {
    getCompetencyBand,
    getPaletteVersion,
    slugifyCompetencyToken,
} from './competenceLevelPalette.js';
import { getBandColor, getBandColorsByLevel } from './competenceLevelColors.js';
import { inkOn } from './colorRamp.js';

// ============================================================================
// CACHE STATE
// ============================================================================

/** @type {object | null} Cached theme colors */
let _cache = null;
/** @type {number} Cache timestamp */
let _cacheTime = 0;
/** @type {number} Palette registry generation the cache was built against */
let _cacheVersion = -1;
/** @type {number} Cache TTL in ms */
const CACHE_TTL = 5000;

/** Fallback for chart text measurement when --font-family-main is unreadable: the same stack variables.css declares. */
const FONT_FALLBACK =
    "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif";

// ============================================================================
// PUBLIC API
// ============================================================================

/**
 * Get common theme colors from CSS custom properties with caching.
 *
 * The cache is shared across all modules and expires after 5 seconds,
 * which is sufficient to handle theme/mode switches while avoiding redundant reads.
 * @param {boolean} [forceRefresh=false] - Skip cache and re-read CSS variables
 * @returns {ThemeColors} Theme color values
 */
export function getThemeColors(forceRefresh = false) {
    const now = Date.now();
    const paletteVersion = getPaletteVersion();
    if (
        !forceRefresh &&
        _cache &&
        now - _cacheTime < CACHE_TTL &&
        _cacheVersion === paletteVersion
    ) {
        return _cache;
    }

    // The one DOM read in this file. Without a document every token resolves to the
    // literal fallback beside it, so the palette stays usable outside a browser.
    const css = typeof document === 'undefined' ? null : getComputedStyle(document.documentElement);
    const get = (prop, fallback) => css?.getPropertyValue(prop)?.trim() || fallback;

    _cache = {
        // ── Chrome / general UI ink ────────────────────────────────
        chrome: {
            text: get('--text-color', '#333'),
            textSecondary: get('--text-secondary', '#666'),
            textDisabled: get('--text-muted', '#999'),
            border: get('--color-border', '#ddd'),
            surface: get('--surface-color', '#ffffff'),
            chartStroke: get('--chart-stroke-color', '#ffffff'),
            chartLabelFill: get('--chart-label-color', '#000000'),
            defaultBarColor: get('--default-bar-color', '#ccc'),
            ringInactive: get('--ring-inactive-color', '#AAAAAA'),
            tableSectionBorder: get('--table-section-border', '#0c5460'),
            primaryBrand: get('--primary-color', '#4a69bb'),
            fontFamily: get('--font-family-main', FONT_FALLBACK),
        },

        // ── Chart-level semantics ──────────────────────────────────
        chart: {
            school: get('--school-average-color', '#000000'),
            state: get('--state-average-color', '#888888'),
            other: get('--other-average-color', '#7B4FA8'),
            domain0: get('--chart-domain0-color', '#E69138'),
            domain1: get('--chart-domain1-color', '#4B89DC'),
            studentPerformance: get('--student-performance-color', '#ff6b6b'),
            classAverage: get('--class-average-color', '#4CAF50'),
            studentPoint: get('--chart-student-point-color', '#2d3748'),
            gridColor: get('--chart-grid-color', '#e0e0e0'),
            primaryColor: get('--chart-primary-color', '#2563eb'),
        },

        // ── SL semantic chart colors ───────────────────────────────
        sl: {
            teachingQuality: get('--sl-teaching-quality', '#9B59B6'),
            selfEfficacy: get('--sl-self-efficacy', '#5B8DEE'),
            group1: get('--sl-group-1', '#87CEEB'),
            group2: get('--sl-group-2', '#1e3a8a'),
        },

        // ── Rating band colors (SL self-efficacy) ──────────────────
        rating: {
            low: get('--sl-rating-low', '#e74c3c'),
            medium: get('--sl-rating-medium', '#f39c12'),
            good: get('--sl-rating-good', '#3498db'),
            excellent: get('--sl-rating-excellent', '#27ae60'),
        },

        // ── Button / interactive chrome ────────────────────────────
        button: {
            primary: get('--button-primary-color', '#0066cc'),
            primaryHover: get('--button-primary-hover', '#004499'),
        },

        // ── Gender colors ─────────────────────────────────────────
        gender: {
            male: get('--gender-male-color', '#4CAF50'),
            female: get('--gender-female-color', '#2196F3'),
            diverse: get('--gender-diverse-color', '#FF9800'),
        },

        // ── Result colors ─────────────────────────────────────────
        result: {
            correct: get('--result-correct', '#4CAF50'),
        },

        // ── Deviation tints (favourable / unfavourable against a baseline) ──
        tint: {
            positive: get('--tint-positive', '#dbe6fb'),
            negative: get('--tint-negative', '#fde0dd'),
            positiveEdge: get('--primary-color', '#3b82f6'),
            negativeEdge: get('--result-incorrect', '#f44336'),
        },

        // ── Competency (KS) palette ───────────────────────────────
        ks: {
            // Every level registered from the data, keyed by its `nameShort`
            // (`A1`, `Ia`, `KS 1`, …) — the scale varies by state, so there is no
            // fixed Roman/Arabic/GER map to key on.
            byLevel: getBandColorsByLevel(),
        },
    };

    _cacheTime = now;
    _cacheVersion = paletteVersion;
    Object.freeze(_cache);
    Object.freeze(_cache.chrome);
    Object.freeze(_cache.chart);
    Object.freeze(_cache.sl);
    Object.freeze(_cache.rating);
    Object.freeze(_cache.button);
    Object.freeze(_cache.gender);
    Object.freeze(_cache.result);
    Object.freeze(_cache.ks);
    Object.freeze(_cache.ks.byLevel);
    return _cache;
}

/**
 * Drop the cached theme colors so the next `getThemeColors()` re-reads the CSS
 * custom properties. Call this after a theme or mode switch (e.g. the KS color
 * theme picker) so JS-baked chart colors reflect the new palette.
 */
export function invalidateThemeColorCache() {
    _cache = null;
    _cacheTime = 0;
    _cacheVersion = -1;
}

/**
 * Get the resolved color for a competence level in any input vocabulary
 * (`A1`, `ks_III`, …). Falls back to the neutral bar color for values
 * that are not registered levels.
 * @param {string|number} level - A competence level in any input vocabulary.
 * @param {string} [scaleId] - Which ladder `level` belongs to. Needed only where one page
 *   holds two ladders sharing a level name (SL's multi-subject views); without it the
 *   answer is the scale that registered the name last.
 * @returns {string} Resolved CSS color value
 */
export function getCompetencyColor(level, scaleId) {
    return getBandColor(level, undefined, scaleId) ?? getThemeColors().chrome.defaultBarColor;
}

/**
 * Resolve the visual appearance metadata for a competence level, or `null` when the
 * value is not a registered level — which is how renderers tell competence-level
 * fields apart from gender / richtig-falsch fields.
 *
 * Every level resolves to one plain solid color; levels sharing a band are separated
 * by lightness in the palette itself (see `shadeSubBand`), so renderers never need to
 * treat a sub-band specially.
 * @param {string|number} level - A competence level in any input vocabulary.
 * @param {string} [scaleId] - Which ladder `level` belongs to; see `getCompetencyColor`
 * @returns {{normalizedLevel: string, baseColor: string, ink: string, patternKey: string, bandIndex: number, scaleId: string}|null} The resolved appearance, or null when the value is not a registered level.
 */
export function getCompetencyAppearance(level, scaleId) {
    const entry = getCompetencyBand(level, scaleId);
    if (!entry) {
        return null;
    }

    // Resolved through the palette by (scale, level) rather than off
    // `getThemeColors().ks.byLevel`, which is keyed by name alone: on a page holding
    // two ladders that share a level name, that object can only hold one of the two
    // colors, so reading it here would undo the registry's scale-awareness.
    const baseColor =
        getBandColor(level, undefined, scaleId) ?? getThemeColors().chrome.defaultBarColor;

    return {
        normalizedLevel: entry.name,
        baseColor,
        // The ink of a label drawn on the band: white while it reads, else dark.
        ink: inkOn(baseColor),
        patternKey: slugifyCompetencyToken(entry.name),
        bandIndex: entry.bandIndex,
        scaleId: entry.scaleId,
    };
}

/**
 * Namespaced by scope so a color's job is explicit at the call site
 * (`colors.ks.byLevel`, `colors.chrome.text`, `colors.status`/`result`, …).
 * @typedef {object} ThemeColors
 * @property {{ text: string, textSecondary: string, textDisabled: string, border: string, surface: string, chartStroke: string, chartLabelFill: string, defaultBarColor: string, ringInactive: string, tableSectionBorder: string, primaryBrand: string, fontFamily: string }} chrome - General UI ink + chart chrome
 * @property {{ school: string, state: string, other: string, domain0: string, domain1: string, studentPerformance: string, classAverage: string, studentPoint: string, gridColor: string, primaryColor: string }} chart - Chart-level semantic colors
 * @property {{ teachingQuality: string, selfEfficacy: string, group1: string, group2: string }} sl - SL semantic chart colors
 * @property {{ low: string, medium: string, good: string, excellent: string }} rating - Self-efficacy rating band colors
 * @property {{ primary: string, primaryHover: string }} button - Button / interactive chrome
 * @property {{ male: string, female: string, diverse: string }} gender - Gender colors
 * @property {{ correct: string }} result - Result colors
 * @property {{ positive: string, negative: string, positiveEdge: string, negativeEdge: string }} tint - Deviation tints and the hue each is a tint of
 * @property {{ byLevel: {[level: string]: string} }} ks - Competence-level palette, keyed by the level's `nameShort`
 */
